import sys

def solve():
    line = sys.stdin.read().strip()
    if not line:
        return
    u, v = map(int, line.split())

    if (u & v) != u or u > v:
        print("-1")
        return

    if u == v:
        if u == 0:
            print(0)
            print()
        else:
            print(1)
            print(u)
        return

    diff = v - u
    if diff % 2 != 0:
        print("-1")
        return

    half = diff // 2

    if (u & half) == 0:
        print(2)
        print(f"{u ^ half} {half}")
    else:
        print(3)
        print(f"{u} {half} {half}")

if __name__ == "__main__":
    solve()
